  <meta property="og:image" content="https://about.snapframe.com/og-image.jpg">

  <!-- Twitter -->
  <meta property="twitter:card" content="summary_large_image">
  <meta property="twitter:url" content="https://about.snapframe.com/">
  <meta property="twitter:title" content="About SnapFrame | Capture, Create & Share What You Love">
  <meta property="twitter:description" content="SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most.">
  <meta property="twitter:image" content="https://about.snapframe.com/og-image.jpg">

  <!-- Favicons -->
  <link rel="icon" type="image/svg+xml" href="favicon.svg">

  <!-- Fonts -->
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;1,400&display=swap" rel="stylesheet">

  <!-- Structured Data -->
  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "Organization",
    "name": "SnapFrame",
    "description": "SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most.",
    "@id": "https://about.snapframe.com/#organization",
    "url": "https://about.snapframe.com",
    "logo": "https://about.snapframe.com/logo.svg",
    "sameAs": [
      "https://www.facebook.com/snapframe",
      "https://www.youtube.com/snapframe",
      "https://x.com/snapframe",
      "https://www.linkedin.com/company/snapframe"
    ]
  }
  </script>

  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --black: #000000;
      --white: #ffffff;
      --purple: #7638FA;
      --purple-light: #9B6BFF;
      --purple-dark: #5A20E8;
      --orange: #FF7A00;
      --orange-light: #FF9A40;
      --gray-50: #F8F8F8;
      --gray-100: #F0F0F0;
      --gray-200: #E0E0E0;
      --gray-400: #A0A0A0;
      --gray-600: #606060;
      --gray-800: #1A1A1A;
      --font: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --radius-sm: 8px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --radius-xl: 32px;
      --radius-pill: 999px;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: var(--font);
      background: var(--white);
      color: var(--black);
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    /* ============ HEADER ============ */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: rgba(255, 255, 255, 0.92);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--gray-100);
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      height: 64px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
    }

    .header-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
      flex-shrink: 0;
    }

    .logo-mark {
      width: 36px;
      height: 36px;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-mark svg {
      width: 20px;
      height: 20px;
      fill: white;
    }

    .logo-text {
      font-size: 20px;
      font-weight: 800;
      color: var(--black);
      letter-spacing: -0.5px;
    }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-login {
      padding: 8px 20px;
      background: var(--black);
      color: var(--white);
      border: none;
      border-radius: var(--radius-pill);
      font-family: var(--font);
      font-size: 14px;
      font-weight: 600;
      cursor: pointer;
      text-decoration: none;
      transition: background 0.2s, transform 0.1s;
      white-space: nowrap;
    }

    .btn-login:hover {
      background: var(--gray-800);
      transform: translateY(-1px);
    }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      cursor: pointer;
      padding: 8px;
      border: none;
      background: none;
      border-radius: var(--radius-sm);
      transition: background 0.2s;
    }

    .hamburger:hover {
      background: var(--gray-100);
    }

    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--black);
      border-radius: 2px;
      transition: transform 0.3s, opacity 0.3s;
      transform-origin: center;
    }

    .hamburger.active span:nth-child(1) {
      transform: translateY(7px) rotate(45deg);
    }

    .hamburger.active span:nth-child(2) {
      opacity: 0;
      transform: scaleX(0);
    }

    .hamburger.active span:nth-child(3) {
      transform: translateY(-7px) rotate(-45deg);
    }

    /* Mobile Nav Overlay */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 64px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 99;
      padding: 32px 24px;
      flex-direction: column;
      gap: 8px;
      overflow-y: auto;
      transform: translateY(-100%);
      transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
    }

    .mobile-nav.open {
      transform: translateY(0);
    }

    .mobile-nav-link {
      display: block;
      padding: 16px 0;
      font-size: 24px;
      font-weight: 700;
      color: var(--black);
      text-decoration: none;
      border-bottom: 1px solid var(--gray-100);
      transition: color 0.2s;
    }

    .mobile-nav-link:hover {
      color: var(--purple);
    }

    .mobile-nav-cta {
      margin-top: 24px;
    }

    /* ============ HERO ============ */
    .hero {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: center;
      overflow: hidden;
      background: var(--black);
      padding-top: 64px;
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 80% 60% at 60% 40%, rgba(118, 56, 250, 0.45) 0%, transparent 60%),
        radial-gradient(ellipse 60% 50% at 85% 70%, rgba(255, 122, 0, 0.35) 0%, transparent 55%),
        radial-gradient(ellipse 40% 40% at 20% 80%, rgba(118, 56, 250, 0.25) 0%, transparent 50%),
        var(--black);
    }

    .hero-grid {
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
      background-size: 60px 60px;
    }

    .hero-inner {
      position: relative;
      z-index: 2;
      max-width: 1280px;
      margin: 0 auto;
      padding: 100px 24px 120px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      align-items: center;
      gap: 64px;
    }

    .hero-content {
      max-width: 560px;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 6px 14px;
      background: rgba(118, 56, 250, 0.2);
      border: 1px solid rgba(118, 56, 250, 0.4);
      border-radius: var(--radius-pill);
      font-size: 12px;
      font-weight: 600;
      color: var(--purple-light);
      letter-spacing: 0.5px;
      text-transform: uppercase;
      margin-bottom: 24px;
    }

    .hero-badge-dot {
      width: 6px;
      height: 6px;
      background: var(--purple-light);
      border-radius: 50%;
      animation: pulse 2s infinite;
    }

    @keyframes pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.5; transform: scale(0.8); }
    }

    .hero-title {
      font-size: clamp(40px, 6vw, 72px);
      font-weight: 800;
      line-height: 1.05;
      letter-spacing: -2px;
      color: var(--white);
      margin-bottom: 24px;
    }

    .hero-title .gradient-text {
      background: linear-gradient(135deg, var(--purple-light) 0%, var(--orange) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero-sub {
      font-size: 18px;
      font-weight: 400;
      line-height: 1.65;
      color: rgba(255, 255, 255, 0.65);
      margin-bottom: 40px;
      max-width: 440px;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      align-items: center;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 32px;
      background: linear-gradient(135deg, var(--purple), var(--purple-dark));
      color: var(--white);
      border: none;
      border-radius: var(--radius-pill);
      font-family: var(--font);
      font-size: 16px;
      font-weight: 700;
      cursor: pointer;
      text-decoration: none;
      transition: transform 0.2s, box-shadow 0.2s;
      box-shadow: 0 8px 32px rgba(118, 56, 250, 0.4);
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 12px 40px rgba(118, 56, 250, 0.55);
    }

    .btn-primary:active {
      transform: translateY(0);
    }

    .hero-visual {
      position: relative;
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .phone-mockup {
      position: relative;
      width: 280px;
      height: 560px;
      background: #111;
      border-radius: 40px;
      border: 2px solid rgba(255,255,255,0.12);
      overflow: hidden;
      box-shadow:
        0 40px 80px rgba(0,0,0,0.6),
        0 0 0 1px rgba(255,255,255,0.06),
        inset 0 0 0 1px rgba(255,255,255,0.04);
      flex-shrink: 0;
    }

    .phone-notch {
      position: absolute;
      top: 16px;
      left: 50%;
      transform: translateX(-50%);
      width: 80px;
      height: 22px;
      background: #111;
      border-radius: 12px;
      z-index: 10;
    }

    .phone-screen {
      width: 100%;
      height: 100%;
      background: linear-gradient(160deg, #1a1a2e 0%, #16213e 40%, #0f3460 100%);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 60px 20px 30px;
      gap: 16px;
    }

    .phone-post {
      width: 100%;
      background: rgba(255,255,255,0.06);
      border-radius: 16px;
      overflow: hidden;
      border: 1px solid rgba(255,255,255,0.08);
    }

    .phone-post-img {
      width: 100%;
      height: 120px;
      background: linear-gradient(135deg, rgba(118,56,250,0.6), rgba(255,122,0,0.6));
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .phone-post-img-inner {
      width: 40px;
      height: 40px;
      background: rgba(255,255,255,0.3);
      border-radius: 50%;
    }

    .phone-post-meta {
      padding: 10px 12px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .phone-avatar {
      width: 24px;
      height: 24px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--purple), var(--orange));
    }

    .phone-likes {
      font-size: 10px;
      color: rgba(255,255,255,0.5);
      font-weight: 600;
    }

    .phone-post-2 {
      width: 100%;
      background: rgba(255,255,255,0.04);
      border-radius: 16px;
      height: 80px;
      border: 1px solid rgba(255,255,255,0.06);
      display: flex;
      align-items: center;
      padding: 12px;
      gap: 10px;
    }

    .phone-story-row {
      display: flex;
      gap: 10px;
      width: 100%;
    }

    .phone-story {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 2px solid transparent;
      background:
        linear-gradient(var(--black), var(--black)) padding-box,
        linear-gradient(135deg, var(--purple), var(--orange)) border-box;
      flex-shrink: 0;
      overflow: hidden;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .phone-story-inner {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: rgba(118,56,250,0.4);
    }

    .phone-glow {
      position: absolute;
      top: -80px;
      right: -80px;
      width: 300px;
      height: 300px;
      background: radial-gradient(circle, rgba(118,56,250,0.3) 0%, transparent 70%);
      pointer-events: none;
    }

    .phone-glow-2 {
      position: absolute;
      bottom: -60px;
      left: -60px;
      width: 250px;
      height: 250px;
      background: radial-gradient(circle, rgba(255,122,0,0.25) 0%, transparent 70%);
      pointer-events: none;
    }

    /* ============ SECTIONS SHARED ============ */
    .section {
      padding: 100px 24px;
    }

    .section-inner {
      max-width: 1280px;
      margin: 0 auto;
    }

    /* ============ FEATURES ============ */
    .features {
      background: var(--white);
    }

    .features-layout {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .section-label {
      display: inline-block;
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      color: var(--purple);
      margin-bottom: 16px;
    }

    .section-title {
      font-size: clamp(28px, 4vw, 48px);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -1.5px;
      margin-bottom: 20px;
    }

    .section-body {
      font-size: 17px;
      line-height: 1.7;
      color: var(--gray-600);
      margin-bottom: 28px;
    }

    .link-arrow {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 15px;
      font-weight: 700;
      color: var(--purple);
      text-decoration: none;
      transition: gap 0.2s;
    }

    .link-arrow:hover {
      gap: 10px;
    }

    .features-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }

    .feature-card {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      padding: 28px 24px;
      border: 1px solid var(--gray-100);
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 16px 40px rgba(0,0,0,0.08);
    }

    .feature-icon {
      width: 48px;
      height: 48px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 14px;
      font-size: 22px;
    }

    .feature-icon.purple { background: rgba(118, 56, 250, 0.12); }
    .feature-icon.orange { background: rgba(255, 122, 0, 0.12); }
    .feature-icon.magenta { background: rgba(255, 56, 180, 0.12); }
    .feature-icon.teal { background: rgba(0, 200, 180, 0.12); }

    .feature-name {
      font-size: 15px;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 6px;
    }

    .feature-desc {
      font-size: 13px;
      color: var(--gray-600);
      line-height: 1.5;
    }

    /* ============ SAFETY ============ */
    .safety {
      background: linear-gradient(135deg, #f0ebff 0%, #fff5eb 100%);
    }

    .safety-layout {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .safety-visual {
      display: flex;
      justify-content: center;
    }

    .safety-card-stack {
      position: relative;
      width: 320px;
      height: 340px;
    }

    .safety-card {
      position: absolute;
      background: var(--white);
      border-radius: var(--radius-xl);
      padding: 28px;
      box-shadow: 0 20px 60px rgba(0,0,0,0.1);
    }

    .safety-card-main {
      top: 0;
      left: 0;
      right: 0;
      z-index: 3;
    }

    .safety-card-bg-1 {
      top: 20px;
      left: -20px;
      right: 20px;
      bottom: -20px;
      z-index: 2;
      opacity: 0.5;
      transform: rotate(-3deg);
    }

    .safety-card-bg-2 {
      top: 40px;
      left: -40px;
      right: 40px;
      bottom: -40px;
      z-index: 1;
      opacity: 0.3;
      transform: rotate(-6deg);
    }

    .safety-icon-row {
      display: flex;
      gap: 12px;
      margin-bottom: 20px;
    }

    .safety-icon-badge {
      width: 52px;
      height: 52px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
    }

    .safety-icon-badge.shield { background: rgba(118,56,250,0.1); }
    .safety-icon-badge.lock { background: rgba(255,122,0,0.1); }
    .safety-icon-badge.eye { background: rgba(0,200,150,0.1); }

    .safety-card-title {
      font-size: 16px;
      font-weight: 700;
      margin-bottom: 8px;
    }

    .safety-card-text {
      font-size: 13px;
      color: var(--gray-600);
      line-height: 1.5;
    }

    .safety-features-list {
      display: flex;
      flex-direction: column;
      gap: 12px;
      margin-top: 24px;
    }

    .safety-feature-item {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 15px;
      color: var(--gray-800);
      font-weight: 500;
    }

    .safety-check {
      width: 24px;
      height: 24px;
      background: rgba(118,56,250,0.1);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      color: var(--purple);
      font-size: 12px;
    }

    /* ============ CREATORS ============ */
    .creators {
      background: var(--black);
      position: relative;
      overflow: hidden;
    }

    .creators-bg {
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 70% 60% at 80% 50%, rgba(255, 122, 0, 0.25) 0%, transparent 60%),
        radial-gradient(ellipse 50% 50% at 10% 60%, rgba(118, 56, 250, 0.3) 0%, transparent 55%);
    }

    .creators-inner {
      position: relative;
      z-index: 2;
    }

    .creators-layout {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .creators .section-title {
      color: var(--white);
    }

    .creators .section-body {
      color: rgba(255,255,255,0.65);
    }

    .creators .link-arrow {
      color: var(--orange-light);
    }

    .creators-stats {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
      margin-top: 32px;
    }

    .stat-card {
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius-lg);
      padding: 24px 20px;
    }

    .stat-number {
      font-size: 36px;
      font-weight: 800;
      letter-spacing: -1.5px;
      background: linear-gradient(135deg, var(--purple-light), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      margin-bottom: 4px;
    }

    .stat-label {
      font-size: 13px;
      color: rgba(255,255,255,0.5);
      font-weight: 500;
    }

    .creators-visual {
      display: flex;
      justify-content: center;
    }

    .creator-profile-grid {
      display: grid;
      grid-template-columns: repeat(3, 80px);
      grid-template-rows: repeat(3, 80px);
      gap: 12px;
    }

    .creator-avatar {
      border-radius: var(--radius-md);
      overflow: hidden;
      position: relative;
    }

    .creator-avatar-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 28px;
      font-weight: 800;
      color: white;
    }

    .creator-avatar.large {
      grid-column: span 2;
      grid-row: span 2;
      border-radius: var(--radius-lg);
    }

    .ca-1 { background: linear-gradient(135deg, #7638FA, #B66EFF); }
    .ca-2 { background: linear-gradient(135deg, #FF7A00, #FFB347); }
    .ca-3 { background: linear-gradient(135deg, #FF3894, #FF7DBF); }
    .ca-4 { background: linear-gradient(135deg, #00C8B4, #4DFFEA); }
    .ca-5 { background: linear-gradient(135deg, #3A86FF, #87C1FF); }

    .creator-verified {
      position: absolute;
      bottom: 6px;
      right: 6px;
      width: 18px;
      height: 18px;
      background: var(--purple);
      border-radius: 50%;
      border: 2px solid rgba(0,0,0,0.5);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 8px;
      color: white;
    }

    /* ============ TAGLINE BANNER ============ */
    .tagline-banner {
      background: linear-gradient(135deg, var(--purple) 0%, var(--purple-dark) 40%, #2D0D8C 100%);
      padding: 80px 24px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .tagline-banner::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.04'%3E%3Ccircle cx='30' cy='30' r='2'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }

    .tagline-text {
      position: relative;
      font-size: clamp(32px, 5vw, 60px);
      font-weight: 800;
      color: var(--white);
      letter-spacing: -2px;
      line-height: 1.1;
      max-width: 800px;
      margin: 0 auto;
    }

    .tagline-text span {
      background: linear-gradient(135deg, #FFD166, #FF9A40);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    /* ============ NEWS ============ */
    .news {
      background: var(--white);
      padding-top: 100px;
      padding-bottom: 100px;
    }

    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 40px;
      padding: 0 24px;
      max-width: 1280px;
      margin-left: auto;
      margin-right: auto;
    }

    .news-header-left .section-label {
      display: block;
    }

    .news-title {
      font-size: clamp(28px, 4vw, 44px);
      font-weight: 800;
      letter-spacing: -1.5px;
      line-height: 1.1;
    }

    .link-view-more {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 10px 20px;
      border: 2px solid var(--black);
      border-radius: var(--radius-pill);
      font-size: 14px;
      font-weight: 700;
      color: var(--black);
      text-decoration: none;
      transition: background 0.2s, color 0.2s;
      white-space: nowrap;
      flex-shrink: 0;
      align-self: center;
    }

    .link-view-more:hover {
      background: var(--black);
      color: var(--white);
    }

    /* Carousel */
    .carousel-wrapper {
      position: relative;
      overflow: hidden;
    }

    .carousel-track {
      display: flex;
      gap: 20px;
      padding: 8px 24px 24px;
      overflow-x: auto;
      scroll-behavior: smooth;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      -ms-overflow-style: none;
      cursor: grab;
    }

    .carousel-track:active {
      cursor: grabbing;
    }

    .carousel-track::-webkit-scrollbar {
      display: none;
    }

    .news-card {
      flex: 0 0 320px;
      background: var(--white);
      border-radius: var(--radius-xl);
      overflow: hidden;
      border: 1px solid var(--gray-100);
      transition: transform 0.25s, box-shadow 0.25s;
      user-select: none;
    }

    .news-card:hover {
      transform: translateY(-6px);
      box-shadow: 0 24px 48px rgba(0,0,0,0.1);
    }

    .news-thumb {
      width: 100%;
      height: 200px;
      position: relative;
      overflow: hidden;
    }

    .news-thumb-img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .news-thumb-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .news-thumb-icon {
      width: 56px;
      height: 56px;
      background: rgba(255,255,255,0.25);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
    }

    .n-thumb-1 { background: linear-gradient(135deg, #7638FA 0%, #FF3894 100%); }
    .n-thumb-2 { background: linear-gradient(135deg, #FF7A00 0%, #FFD166 100%); }
    .n-thumb-3 { background: linear-gradient(135deg, #3A86FF 0%, #7638FA 100%); }
    .n-thumb-4 { background: linear-gradient(135deg, #00C8B4 0%, #3A86FF 100%); }

    .news-body {
      padding: 24px;
    }

    .news-tags {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-bottom: 14px;
    }

    .news-tag {
      display: inline-block;
      padding: 4px 10px;
      background: rgba(118,56,250,0.1);
      color: var(--purple);
      border-radius: var(--radius-pill);
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.5px;
      text-transform: uppercase;
    }

    .news-tag.orange {
      background: rgba(255,122,0,0.1);
      color: var(--orange);
    }

    .news-card-title {
      font-size: 16px;
      font-weight: 700;
      line-height: 1.4;
      color: var(--black);
      margin-bottom: 12px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-date {
      font-size: 13px;
      color: var(--gray-400);
      font-weight: 500;
    }

    /* Scroll indicators */
    .carousel-nav {
      display: flex;
      justify-content: center;
      gap: 8px;
      padding: 16px 0 0;
    }

    .carousel-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--gray-200);
      border: none;
      cursor: pointer;
      transition: background 0.2s, transform 0.2s;
      padding: 0;
    }

    .carousel-dot.active {
      background: var(--purple);
      transform: scale(1.3);
    }

    /* ============ CTA DOWNLOAD ============ */
    .cta-download {
      background: var(--black);
      padding: 100px 24px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .cta-download-bg {
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 60% 70% at 50% 50%, rgba(118, 56, 250, 0.3) 0%, transparent 60%);
    }

    .cta-download-inner {
      position: relative;
      z-index: 2;
      max-width: 600px;
      margin: 0 auto;
    }

    .cta-headline {
      font-size: clamp(40px, 6vw, 72px);
      font-weight: 800;
      letter-spacing: -2.5px;
      line-height: 1.0;
      color: var(--white);
      margin-bottom: 8px;
    }

    .cta-subheadline {
      font-size: clamp(40px, 6vw, 72px);
      font-weight: 800;
      letter-spacing: -2.5px;
      line-height: 1.0;
      background: linear-gradient(135deg, var(--purple-light), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      margin-bottom: 48px;
    }

    .store-buttons {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .store-btn {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 24px;
      background: var(--white);
      color: var(--black);
      border-radius: var(--radius-lg);
      text-decoration: none;
      transition: transform 0.2s, box-shadow 0.2s;
      min-width: 180px;
    }

    .store-btn:hover {
      transform: translateY(-3px);
      box-shadow: 0 16px 40px rgba(255,255,255,0.2);
    }

    .store-btn-icon {
      font-size: 28px;
      flex-shrink: 0;
    }

    .store-btn-text {
      text-align: left;
    }

    .store-btn-label {
      font-size: 11px;
      color: var(--gray-600);
      font-weight: 500;
      line-height: 1;
      margin-bottom: 2px;
    }

    .store-btn-name {
      font-size: 16px;
      font-weight: 800;
      color: var(--black);
      line-height: 1;
    }

    /* ============ FOOTER ============ */
    .footer {
      background: var(--gray-50);
      border-top: 1px solid var(--gray-200);
    }

    .footer-main {
      max-width: 1280px;
      margin: 0 auto;
      padding: 64px 24px 48px;
    }

    .footer-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 56px;
      flex-wrap: wrap;
      gap: 24px;
    }

    .footer-brand {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
    }

    .footer-tagline {
      font-size: 14px;
      color: var(--gray-400);
      font-weight: 500;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 32px;
      margin-bottom: 48px;
    }

    .footer-col-title {
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 1px;
      text-transform: uppercase;
      color: var(--black);
      margin-bottom: 16px;
    }

    .footer-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer-links a {
      font-size: 14px;
      color: var(--gray-600);
      text-decoration: none;
      transition: color 0.2s;
      font-weight: 500;
    }

    .footer-links a:hover {
      color: var(--black);
    }

    .ext-link::after {
      content: ' ↗';
      font-size: 10px;
      opacity: 0.6;
    }

    .footer-divider {
      height: 1px;
      background: var(--gray-200);
      margin-bottom: 28px;
    }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-lang {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 13px;
      color: var(--gray-600);
      font-weight: 500;
      cursor: pointer;
      padding: 6px 12px;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-pill);
      background: var(--white);
      transition: border-color 0.2s;
    }

    .footer-lang:hover {
      border-color: var(--gray-400);
    }

    .footer-social {
      display: flex;
      gap: 8px;
    }

    .social-icon {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: var(--white);
      border: 1px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      text-decoration: none;
      transition: background 0.2s, border-color 0.2s, transform 0.2s;
    }

    .social-icon:hover {
      background: var(--black);
      border-color: var(--black);
      transform: translateY(-2px);
    }

    .footer-legal {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      font-size: 12px;
      color: var(--gray-400);
    }

    .footer-legal a {
      color: var(--gray-400);
      text-decoration: none;
      transition: color 0.2s;
    }

    .footer-legal a:hover {
      color: var(--black);
    }

    .footer-legal-sep {
      color: var(--gray-200);
    }

    /* ============ RESPONSIVE ============ */
    @media (max-width: 1024px) {
      .footer-grid {
        grid-template-columns: repeat(3, 1fr);
      }
    }

    @media (max-width: 768px) {
      .hamburger { display: flex; }

      .mobile-nav { display: flex; }

      .hero-inner {
        grid-template-columns: 1fr;
        text-align: center;
        padding: 80px 24px 80px;
      }

      .hero-visual {
        order: -1;
      }

      .phone-mockup {
        width: 220px;
        height: 440px;
      }

      .hero-actions {
        justify-content: center;
      }

      .hero-sub {
        margin-left: auto;
        margin-right: auto;
      }

      .features-layout,
      .safety-layout,
      .creators-layout {
        grid-template-columns: 1fr;
        gap: 48px;
      }

      .safety-visual {
        order: -1;
      }

      .safety-card-stack {
        width: 280px;
        height: 300px;
        margin: 0 auto;
      }

      .creators-stats {
        grid-template-columns: 1fr 1fr;
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-top {
        flex-direction: column;
        align-items: flex-start;
      }

      .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
      }

      .news-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 16px;
      }

      .cta-headline, .cta-subheadline {
        font-size: clamp(36px, 10vw, 64px);
      }
    }

    @media (max-width: 480px) {
      .section { padding: 72px 24px; }

      .features-grid {
        grid-template-columns: 1fr;
      }

      .creators-stats {
        grid-template-columns: 1fr 1fr;
      }

      .footer-grid {
        grid-template-columns: 1fr 1fr;
      }

      .news-card {
        flex: 0 0 280px;
      }
    }
  </style>
</head>
<body>

  <!-- ===== HEADER ===== -->
  <header class="header" id="header">
    <div class="header-inner">
      <a href="#" class="header-logo">
        <div class="logo-mark">
          <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
            <path d="M12 2C6.477 2 2 6.477 2 12s4.477 10 10 10 10-4.477 10-10S17.523 2 12 2zm0 2a8 8 0 110 16A8 8 0 0112 4zm0 2a6 6 0 100 12A6 6 0 0012 6zm0 2a4 4 0 110 8 4 4 0 010-8zm0 2a2 2 0 100 4 2 2 0 000-4z"/>
