  </header>

  <!-- Mobile Nav -->
  <nav class="mobile-nav" id="mobileNav" role="navigation" aria-label="Mobile navigation">
    <a href="#features" class="mobile-nav-link" onclick="closeMobileNav()">Features</a>
    <a href="#safety" class="mobile-nav-link" onclick="closeMobileNav()">Safety</a>
    <a href="#creators" class="mobile-nav-link" onclick="closeMobileNav()">Creators</a>
    <a href="#news" class="mobile-nav-link" onclick="closeMobileNav()">News</a>
    <a href="#" class="mobile-nav-link" onclick="closeMobileNav()">About</a>
