  </nav>


  <!-- ===== HERO ===== -->
  <section class="hero">
    <div class="hero-bg"></div>
    <div class="hero-grid"></div>
    <div class="hero-inner">
      <div class="hero-content">
        <div class="hero-badge">
          <div class="hero-badge-dot"></div>
          Now available worldwide
        </div>
        <h1 class="hero-title">
          SnapFrame brings you
          <span class="gradient-text">closer</span>
          to the people and things you love
        </h1>
        <p class="hero-sub">
          Capture, create, and share what you love with the people who matter most — with Clips, Stories, DMs, and more.
        </p>
        <div class="hero-actions">
          <a href="#" class="btn-primary">Try it now</a>
        </div>
      </div>
      <div class="hero-visual">
        <div class="phone-glow"></div>
        <div class="phone-glow-2"></div>
        <div class="phone-mockup">
          <div class="phone-notch"></div>
          <div class="phone-screen">
