  <script>
    // ===== HAMBURGER MENU =====
    const hamburger = document.getElementById('hamburger');
    const mobileNav = document.getElementById('mobileNav');
    const body = document.body;

    hamburger.addEventListener('click', () => {
      const isOpen = mobileNav.classList.toggle('open');
      hamburger.classList.toggle('active', isOpen);
      hamburger.setAttribute('aria-expanded', isOpen);
      body.style.overflow = isOpen ? 'hidden' : '';
    });

    function closeMobileNav() {
      mobileNav.classList.remove('open');
      hamburger.classList.remove('active');
      hamburger.setAttribute('aria-expanded', 'false');
      body.style.overflow = '';
    }

    // Close on outside click
    document.addEventListener('click', (e) => {
      if (!hamburger.contains(e.target) && !mobileNav.contains(e.target)) {
        if (mobileNav.classList.contains('open')) closeMobileNav();
      }
    });

    // ===== NEWS CAROUSEL =====
    const track = document.getElementById('carouselTrack');
    const dots = document.querySelectorAll('.carousel-dot');

    // Drag-to-scroll on desktop
    let isDragging = false;
    let startX = 0;
    let scrollStart = 0;

    track.addEventListener('mousedown', (e) => {
      isDragging = true;
      startX = e.clientX;
      scrollStart = track.scrollLeft;
      track.style.cursor = 'grabbing';
      e.preventDefault();
    });

    document.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      const dx = e.clientX - startX;
      track.scrollLeft = scrollStart - dx;
    });

    document.addEventListener('mouseup', () => {
      isDragging = false;
      track.style.cursor = 'grab';
      updateDots();
    });

    // Update active dot based on scroll position
    function updateDots() {
      const cards = track.querySelectorAll('.news-card');
      const trackRect = track.getBoundingClientRect();
      let activeIdx = 0;
      let minDist = Infinity;

      cards.forEach((card, i) => {
        const cardRect = card.getBoundingClientRect();
        const dist = Math.abs(cardRect.left - trackRect.left);
        if (dist < minDist) {
          minDist = dist;
          activeIdx = i;
        }
      });

      dots.forEach((dot, i) => {
        dot.classList.toggle('active', i === activeIdx);
      });
    }

    track.addEventListener('scroll', updateDots, { passive: true });

    // Dot click to scroll
    dots.forEach((dot) => {
      dot.addEventListener('click', () => {
        const idx = parseInt(dot.dataset.index);
        const cards = track.querySelectorAll('.news-card');
        const card = cards[idx];
        if (card) {
          const trackPad = 24;
          track.scrollTo({
            left: card.offsetLeft - trackPad,
            behavior: 'smooth'
          });
        }
      });
    });

    // Touch swipe support
    let touchStartX = 0;
    track.addEventListener('touchstart', (e) => {
      touchStartX = e.touches[0].clientX;
    }, { passive: true });

    track.addEventListener('touchend', (e) => {
      const dx = e.changedTouches[0].clientX - touchStartX;
      if (Math.abs(dx) > 50) {
        const cards = track.querySelectorAll('.news-card');
        const trackRect = track.getBoundingClientRect();
        let activeIdx = 0;
        let minDist = Infinity;
        cards.forEach((card, i) => {
          const dist = Math.abs(card.getBoundingClientRect().left - trackRect.left);
          if (dist < minDist) { minDist = dist; activeIdx = i; }
        });

        const next = dx < 0
          ? Math.min(activeIdx + 1, cards.length - 1)
          : Math.max(activeIdx - 1, 0);

        track.scrollTo({
          left: cards[next].offsetLeft - 24,
          behavior: 'smooth'
        });
      }
      setTimeout(updateDots, 350);
    }, { passive: true });

    // ===== HEADER SCROLL EFFECT =====
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.style.boxShadow = window.scrollY > 10
        ? '0 2px 20px rgba(0,0,0,0.08)'
        : 'none';
    }, { passive: true });
  </script>

